import type { BusinessAction, BusinessPermissionContext } from './business-permissions';

export type PermissionRouteKind = 'business' | 'admin' | 'protocol' | 'auxiliary' | 'view' | 'denied';
export interface PermissionRouteDefinition {
  method: string;
  path: string;
  kind: PermissionRouteKind;
  permission?: BusinessPermissionContext;
  /** These handlers must authorize the real record branch before mutation. */
  recordDependent?: { operationId: string; candidateActions: readonly BusinessAction[]; service: string };
  /** Read-only selectors filter every returned record by these operation scopes. */
  selectorActions?: readonly BusinessAction[];
  /** Shared upload/selectors admit one action; handlers enforce the exact owner operation. */
  selectorPermissions?: readonly BusinessPermissionContext[];
  refreshQueries?: readonly string[];
  passiveRefreshValues?: readonly string[];
  dependencies?: readonly BusinessPermissionContext[];
  refreshPermission?: BusinessPermissionContext;
  /** Classification does not bypass any signature, identity, feature or business checks. */
  protection?: string;
  source: string;
}

